'use strict';

/* eslint max-nested-callbacks: ["error", 5] -- Nested reference layout matrices and synchronous tape rejection assertions. */

// MODULES //

var vm = require( 'vm' );
var tape = require( 'tape' );
var Number = require( '@stdlib/number/ctor' );
var Proxy = require( '@stdlib/proxy/ctor' );
var SharedArrayBuffer = require( '@stdlib/array/shared-buffer' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var Float64Array = require( '@stdlib/array/float64' );
var main = require( './../lib/main.js' );
var native = require( './../lib' );
var factory = require( './../lib/factory.js' );
var base = require( './../lib/base.js' );
var eligible = require( './../lib/can_use_native.js' );
var snapshot = require( './helpers.js' ).snapshot;
var bits = require( './helpers.js' ).bits;


// TESTS //

tape('dpbequ: complete failed outputs and explicit first-zero reduction', function test(t) {
	[
		main,
		native
	].forEach(function backend(f) {
		var sc;
		var am;
		var a;
		var s;
		a = new Float64Array([
			4,
			-1,
			100,
			9
		]);
		s = new Float64Array(4);
		sc = new Float64Array([-91]);
		am = new Float64Array([-92]);
		t.strictEqual(f(102, 122, 4, 0, a, 1, s, sc, am), 2, 'first one-based nonpositive');
		t.deepEqual(Array.prototype.slice.call(s), [
			4,
			-1,
			100,
			9
		], 'all diagonals copied, including suffix');
		t.strictEqual(am[0], 100, 'AMAX includes later columns');
		t.strictEqual(sc[0], -91, 'SCOND exact caller sentinel unchanged');
		a = new Float64Array([
			-0,
			+0
		]);
		t.strictEqual(f(102, 122, 2, 0, a, 1, s, sc, am), 1, 'zero fails');
		t.strictEqual(bits(am[0]), '8000000000000000', 'deliberate first-tie AMAX minus-zero');
		t.strictEqual(bits(s[0]), '8000000000000000', 'copied minus-zero');
		t.strictEqual(bits(s[1]), '0000000000000000', 'copied plus-zero');
	});
	t.end();
});
tape('dpbequ: empty accesses only validated active scalar outputs', function test(t) {
	[
		main,
		native
	].forEach(function backend(f) {
		var trap;
		var sc;
		var am;
		trap = new Proxy({}, {
			'get': function get() {
				throw new Error('inactive read');
			}
		});
		sc = new Float64Array([
			91,
			92,
			93
		]);
		am = new Float64Array([
			94,
			95,
			96
		]);
		t.strictEqual(f.ndarray(121, 0, 2147483646, trap, trap, trap, trap, trap, trap, trap, sc, 1, am, 2), 0, 'inactive ndarray operands ignored');
		t.deepEqual(Array.prototype.slice.call(sc), [
			91,
			1,
			93
		], 'only active SCOND');
		t.deepEqual(Array.prototype.slice.call(am), [
			94,
			95,
			0
		], 'only active AMAX');
		t.strictEqual(f(102, 122, 0, 2147483646, trap, 2147483647, trap, sc, am), 0, 'empty main before unused native casts');
		t.throws(function bad() {
			f(102, 122, 0, 8, trap, 1, trap, sc, am);
		}, RangeError, 'leading dimension required even empty');
		t.throws(function bad() {
			f.ndarray(121, 0, 0, trap, trap, trap, trap, trap, trap, trap, sc, 0, sc, 0);
		}, RangeError, 'active empty scalars must be disjoint');
	});
	t.end();
});
tape('dpbequ: invalid metadata, finite domain and aliases never mutate outputs', function test(t) {
	[
		main,
		native
	].forEach(function backend(f) {
		var initial;
		var storage;
		var views;
		var bads;
		var sc;
		var am;
		var vs;
		var a;
		var s;
		var i;
		var j;
		a = new Float64Array([
			4,
			9,
			16,
			25
		]);
		s = new Float64Array([
			11,
			12,
			13,
			14
		]);
		sc = new Float64Array([15]);
		am = new Float64Array([16]);
		bads = [
			NaN,
			Infinity,
			-1,
			2147483647,
			0.5,
			'2',
			new Number(2)
		];
		bads.forEach(function each(n) {
			initial = [
				snapshot(a),
				snapshot(s),
				snapshot(sc),
				snapshot(am)
			];
			t.throws(function bad() {
				f(102, 122, n, 0, a, 1, s, sc, am);
			}, RangeError, 'dimension rejected');
			t.deepEqual([
				snapshot(a),
				snapshot(s),
				snapshot(sc),
				snapshot(am)
			], initial, 'dimension rejection preserves bytes');
		});
		[
			NaN,
			Infinity,
			-Infinity
		].forEach(function each(v) {
			a[3] = v;
			initial = [
				snapshot(a),
				snapshot(s),
				snapshot(sc),
				snapshot(am)
			];
			t.throws(function bad() {
				f(102, 122, 4, 0, a, 1, s, sc, am);
			}, RangeError, 'late nonfinite diagonal rejected before earlier writes');
			t.deepEqual([
				snapshot(a),
				snapshot(s),
				snapshot(sc),
				snapshot(am)
			], initial, 'late rejection preserves all bytes');
		});
		a[3] = 25;
		t.throws(function bad() {
			f.ndarray(122, 2, 1, a, 1, 1, 0, s, 1, 0, sc, 0, am, 0);
		}, RangeError, 'colliding full-band view rejected');
		t.throws(function bad() {
			f.ndarray(122, 2, 0, a, 0, -1, 0, s, 1, 0, sc, 0, am, 0);
		}, RangeError, 'negative end beyond backing rejected');
		t.throws(function bad() {
			f.ndarray(122, 2, 0, a, 0, 1, 0, s, 0, 0, sc, 0, am, 0);
		}, RangeError, 'output broadcasts rejected');
		storage = new ArrayBuffer(512);
		views = [
			new Float64Array(storage, 0, 8),
			new Float64Array(storage, 128, 8),
			new Float64Array(storage, 256, 8),
			new Float64Array(storage, 384, 8)
		];
		for (i = 0; (i < 4); i++) {
			for (j = (i + 1); (j < 4); j++) {
				vs = views.slice();
				vs[j] = new Float64Array(storage, (i * 128), 8);
				views[0].fill(4);
				initial = views.map(snapshot);
				t.throws(f.bind(null, 102, 122, 2, 0, vs[0], 1, vs[1], vs[2], vs[3]), RangeError, ((('pairwise alias ' + i) + ',') + j));
				t.deepEqual(views.map(snapshot), initial, 'all storage preserved');
			}
		}
		views.forEach(function fill(v) {
			v.fill(4);
		});
		t.strictEqual(f(102, 122, 2, 0, views[0], 1, views[1], views[2], views[3]), 0, 'same backing disjoint views supported');
	});
	t.end();
});
tape('dpbequ: captured intrinsic branding and fallback protocol', function test(t) {
	var wrapped;
	var calls;
	var sc;
	var am;
	var s;
	[
		main,
		native
	].forEach(function backend(f) {
		var sc;
		var am;
		var a;
		var s;
		a = new Float64Array([4]);
		s = new Float64Array(1);
		sc = new Float64Array(1);
		am = new Float64Array(1);
		Object.defineProperty(a, 'length', {
			'get': function get() {
				throw new Error('shadow getter');
			}
		});
		Object.defineProperty(s, 'buffer', {
			'get': function get() {
				throw new Error('shadow getter');
			}
		});
		t.strictEqual(f(102, 122, 1, 0, a, 1, s, sc, am), 0, 'shadow properties ignored');
		a = vm.runInNewContext('new Float64Array([9])');
		t.strictEqual(f(102, 122, 1, 0, a, 1, s, sc, am), 0, 'genuine crossrealm supported');
		t.strictEqual(s[0], (1 / 3), 'crossrealm output');
		a = new Float64Array(new SharedArrayBuffer(8));
		a[0] = 4;
		t.throws(function bad() {
			f(102, 122, 1, 0, a, 1, s, sc, am);
		}, TypeError, 'shared storage rejected');
		a = new Float64Array([4]);
		t.throws(function bad() {
			f(102, 122, 1, 0, new Proxy(a, {}), 1, s, sc, am);
		}, TypeError, 'proxy rejected');
	});
	calls = 0;
	wrapped = factory(function dispatch() {
		calls += 1;
		return base.apply(null, arguments);
	}, eligible, base);
	s = new Float64Array(1);
	sc = new Float64Array(1);
	am = new Float64Array(1);
	t.strictEqual(wrapped.ndarray(122, 1, 0, new Float64Array([4]), 9007199254740991, 9007199254740991, 0, s, 9007199254740991, 0, sc, 0, am, 0), 0, 'valid wider unused metadata uses actual JS');
	t.strictEqual(calls, 0, 'native not invoked on fallback');
	t.strictEqual(wrapped(102, 122, 1, 0, new Float64Array([4]), 1, s, sc, am), 0, 'ordinary metadata dispatches');
	t.strictEqual(calls, 1, 'dispatch actually invoked');
	wrapped = factory(function fail() {
		throw new RangeError('native alias error');
	}, function yes() {
		return true;
	}, function badFallback() {
		t.fail('must not fall back after native error');
	});
	t.throws(function bad() {
		wrapped(102, 122, 1, 0, new Float64Array([4]), 1, s, sc, am);
	}, /native alias error/, 'native rejection propagates');
	t.end();
});
